const { withAndroidManifest, withAppBuildGradle } = require("@expo/config-plugins");

// Play Console flagged two things on release 18 (1.0.2) that live in native
// files regenerated by `expo prebuild`, so they're fixed here rather than by
// hand in android/:
//
// 1. "Required hardware feature declarations are restricting your app's
//    availability" (android.hardware.screen.portrait). Removing the portrait
//    lock (app.json `orientation: "default"`) stops the *implied* feature;
//    declaring these features as optional also stops any library manifest from
//    re-introducing a hard requirement. Camera is optional too: devices without
//    a rear camera (some tablets, Chromebooks, XR) can still type barcodes in.
//
// 2. "Your R8 configuration could be causing higher memory usage". The React
//    Native template uses proguard-android.txt, which contains -dontoptimize.
//    proguard-android-optimize.txt lets R8 run its optimisation passes.
const OPTIONAL_FEATURES = [
  "android.hardware.camera",
  "android.hardware.camera.any",
  "android.hardware.camera.autofocus",
  "android.hardware.camera.flash",
  "android.hardware.screen.portrait",
  "android.hardware.screen.landscape",
  "android.hardware.touchscreen",
];

function withOptionalFeatures(config) {
  return withAndroidManifest(config, (config) => {
    const manifest = config.modResults.manifest;
    manifest.$["xmlns:tools"] = "http://schemas.android.com/tools";

    const features = (manifest["uses-feature"] || []).filter(
      (f) => !OPTIONAL_FEATURES.includes(f.$["android:name"])
    );
    for (const name of OPTIONAL_FEATURES) {
      features.push({
        $: { "android:name": name, "android:required": "false", "tools:replace": "android:required" },
      });
    }
    manifest["uses-feature"] = features;

    // Belt and braces: never ship a fixed screenOrientation on any activity.
    for (const app of manifest.application || []) {
      for (const activity of app.activity || []) {
        delete activity.$["android:screenOrientation"];
      }
    }
    return config;
  });
}

function withOptimizedR8(config) {
  return withAppBuildGradle(config, (config) => {
    config.modResults.contents = config.modResults.contents.replace(
      /getDefaultProguardFile\(\s*["']proguard-android\.txt["']\s*\)/g,
      'getDefaultProguardFile("proguard-android-optimize.txt")'
    );
    return config;
  });
}

module.exports = function withAndroidStoreCompliance(config) {
  return withOptimizedR8(withOptionalFeatures(config));
};
